// Bundles Eruda (https://github.com/liriliri/eruda, MIT) for the offline
// console's built-in dev tools (the ⋮ button in its header): copies the
// pinned package's eruda.js into web/devtools.generated.js, which the Worker
// and scripts/build-offline.mjs put inside saints-service.html.
//
//   npm run build:devtools     (after npm install; re-run when eruda is bumped)
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(path.join(ROOT, 'package.json'));
const pkg = require('eruda/package.json');
let code = await readFile(require.resolve('eruda/eruda.js'), 'utf8');
// The source map isn't shipped: a file:// page would only 404 on it.
code = code.replace(/\n?\/\/# sourceMappingURL=\S+\s*$/, '\n');
if (!/^\/\*! eruda v/.test(code)) throw new Error('eruda.js does not look like the Eruda build');

const out = path.join(ROOT, 'web/devtools.generated.js');
await writeFile(out, `// Generated by npm run build:devtools from eruda@${pkg.version}. Do not edit.
// Eruda — https://github.com/liriliri/eruda — Copyright (c) liriliri, MIT License.
export const ERUDA_VERSION = ${JSON.stringify(pkg.version)};
export default ${JSON.stringify(code)};
`);
console.log(`Wrote ${path.relative(ROOT, out)} (eruda ${pkg.version}, ${(code.length / 1024).toFixed(0)} KB)`);
